const r=t=>new Promise(e=>setTimeout(e,t)),i={async createProject(t){var e;if(await r(900),!((e=t.title)!=null&&e.trim()))throw new Error("Project title is required");return{...t,id:"prj-"+Math.random().toString(36).slice(2,7),status:"open",createdAt:new Date().toISOString().slice(0,10),milestones:[]}},async submitBid(t){var e;if(await r(800),!t.price||t.price<=0)throw new Error("Enter a valid proposed price");if(!((e=t.proposal)!=null&&e.trim()))throw new Error("Proposal cannot be empty");return{...t,id:"bid-"+Math.random().toString(36).slice(2,7),status:"pending",createdAt:new Date().toISOString().slice(0,10)}},async acceptBid(t){return await r(700),{...t,status:"accepted"}}};export{i as projectService};
